-- Hermosa OS update-0099: Ads advisor daily data (Meta ads per ad, per day, written by Windsor.ai). Safe to run again.
-- SQL Editor: https://supabase.com/dashboard/project/bnopatuopnenbdhrecdt/sql/new
-- update-0099 (CHRIS Nov 27): "a tailored, ROAS based, market based and industry radar based complete recommendation
-- feature ... if the ads data is not yet real time data from ads manager, this should still be refreshable or at least
-- refreshes daily."
--   1. ads_feed.meta_ads_daily: one row per ad per day (spend before VAT, chats, reach, frequency, budgets, status,
--      targeting). Windsor.ai adds new rows every day; it starts with Oct 20 – Nov 27 2026 so the advisor works now.
--      It lives in its own schema "ads_feed", which the app's users (anon/authenticated) can't reach.
--   2. windsor_writer: the login Windsor uses. It can only add and update rows in that one table. It has no password
--      until you set one (step below), it can't read any Hermosa OS data, and it can't run any Hermosa OS function.
--   3. ads_feed_rows(): how the Ads page reads the feed (owners, GM, finance, auditors only).
-- CHECK FIRST (changes nothing):
-- select case when to_regclass('ads_feed.meta_ads_daily') is not null then 'ALREADY RUN: tick the box on your To-Do' else 'NOT RUN YET: run the rest of this file' end as result;
--
-- AFTER RUNNING (only if you picked the Windsor daily export):
--   a. Make your own long password (a password manager can make one; 24+ characters). Do NOT send it to Claude.
--   b. Run this one line in the SQL Editor with your password between the quotes:
--        ALTER ROLE windsor_writer PASSWORD 'your-own-long-password';
--   c. In Windsor (the link on your To-Do) add a Supabase destination: host = the "Session pooler" host from
--      Supabase > Connect (aws-...pooler.supabase.com), port 5432, database postgres,
--      user windsor_writer.bnopatuopnenbdhrecdt, your password, schema ads_feed, table meta_ads_daily, daily schedule.
--   d. Tell Claude it's saved: Claude sets the fields and checks the first rows arrive.

CREATE SCHEMA IF NOT EXISTS ads_feed;
REVOKE ALL ON SCHEMA ads_feed FROM PUBLIC;

-- 1. The daily feed. Column names are Windsor's field names, so Windsor writes straight into it.
CREATE TABLE IF NOT EXISTS ads_feed.meta_ads_daily (
  date date NOT NULL,
  account_id text,
  account_name text,
  actor_id text,                 -- the Facebook page the ad ran on (decides the branch)
  campaign_id text,
  campaign text,
  adset_id text,
  adset_name text,
  ad_id text,
  ad_name text,
  spend numeric,                 -- pesos BEFORE VAT
  impressions numeric,
  reach numeric,
  frequency numeric,
  clicks numeric,
  actions_onsite_conversion_messaging_conversation_started_7d numeric,  -- new Messenger chats
  adset_daily_budget numeric,    -- centavos
  campaign_daily_budget numeric, -- centavos
  adset_effective_status text,
  ad_effective_status text,
  adset_targeting text,          -- Meta's targeting JSON
  _source text NOT NULL DEFAULT 'windsor',
  _loaded_at timestamptz NOT NULL DEFAULT now()
);
-- No unique key on purpose: if Windsor re-sends a day, the newest copy wins when the page reads it.
CREATE INDEX IF NOT EXISTS meta_ads_daily_date ON ads_feed.meta_ads_daily (date, ad_id, _loaded_at DESC);
CREATE INDEX IF NOT EXISTS meta_ads_daily_adset ON ads_feed.meta_ads_daily (adset_id, date DESC);
REVOKE ALL ON ads_feed.meta_ads_daily FROM PUBLIC, anon, authenticated;

-- 2. Windsor's login: no password yet (step b above), at most 3 connections, sees only ads_feed.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'windsor_writer') THEN
    CREATE ROLE windsor_writer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 3;
  END IF;
END $$;
ALTER ROLE windsor_writer SET search_path = ads_feed;
ALTER ROLE windsor_writer SET statement_timeout = '60s';
GRANT USAGE ON SCHEMA ads_feed TO windsor_writer;
REVOKE CREATE ON SCHEMA ads_feed FROM windsor_writer;
REVOKE ALL ON SCHEMA public FROM windsor_writer;
-- Add and correct rows only (SELECT is needed to update a matching row). No delete.
GRANT SELECT, INSERT, UPDATE ON ads_feed.meta_ads_daily TO windsor_writer;
-- If Windsor's first run says it needs to delete old rows of the same days, run this one extra line:
--   GRANT DELETE ON ads_feed.meta_ads_daily TO windsor_writer;
ALTER TABLE ads_feed.meta_ads_daily ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS meta_ads_daily_windsor ON ads_feed.meta_ads_daily;
CREATE POLICY meta_ads_daily_windsor ON ads_feed.meta_ads_daily FOR ALL TO windsor_writer USING (true) WITH CHECK (true);

-- No SECURITY DEFINER function Windsor can call: any that is still open to everyone (PUBLIC) is closed, and the app's
-- own roles keep exactly the access they had.
DO $$
DECLARE f record; r text;
BEGIN
  FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE p.prosecdef AND n.nspname IN ('public', 'private', 'ads_feed')
             AND has_function_privilege('windsor_writer', p.oid, 'EXECUTE') LOOP
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, f.sig, 'EXECUTE') THEN
        EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', f.sig, r);
      END IF;
    END LOOP;
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC', f.sig);
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
             WHERE p.prosecdef AND has_schema_privilege('windsor_writer', n.oid, 'USAGE')
               AND has_function_privilege('windsor_writer', p.oid, 'EXECUTE')) THEN
    RAISE EXCEPTION 'windsor_writer can still run a SECURITY DEFINER function';
  END IF;
END $$;

-- 3. The reader for the Ads page: one row per ad per day (newest copy), Hermosa's 4 pages only, up to 120 days back,
--    plus each ad set's latest targeting and when the feed last updated.
CREATE OR REPLACE FUNCTION public.ads_feed_rows(p_from date DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Manila')::date;
  v_from date;
  v_pages text[] := ARRAY['103117851723422', '101404945363588', '112393681804031', '257589974108824'];
  v_rows jsonb; v_tg jsonb; v_last date; v_loaded timestamptz; v_src text;
BEGIN
  IF NOT (private.is_management(private.current_user_id()) OR private.has_role(ARRAY['FINANCE','AUDITOR'], NULL)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;
  v_from := greatest(coalesce(p_from, v_today - 42), v_today - 120);
  WITH latest AS (
    SELECT DISTINCT ON (d.date, d.ad_id) d.*
    FROM ads_feed.meta_ads_daily d
    WHERE d.date >= v_from AND d.date <= v_today AND d.actor_id = ANY (v_pages) AND d.ad_id IS NOT NULL
    ORDER BY d.date, d.ad_id, d._loaded_at DESC
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'd', l.date, 'page', l.actor_id, 'cid', l.campaign_id, 'c', l.campaign, 'sid', l.adset_id, 's', l.adset_name,
           'aid', l.ad_id, 'a', l.ad_name, 'sp', l.spend, 'im', l.impressions, 'rc', l.reach, 'fq', l.frequency,
           'cl', l.clicks, 'm', l.actions_onsite_conversion_messaging_conversation_started_7d,
           'sb', l.adset_daily_budget, 'cb', l.campaign_daily_budget, 'ss', l.adset_effective_status, 'as', l.ad_effective_status)
           ORDER BY l.date, l.ad_id), '[]'::jsonb),
         max(l.date)
    INTO v_rows, v_last
  FROM latest l;
  SELECT coalesce(jsonb_object_agg(t.adset_id, t.adset_targeting), '{}'::jsonb) INTO v_tg
  FROM (SELECT DISTINCT ON (d.adset_id) d.adset_id, d.adset_targeting
        FROM ads_feed.meta_ads_daily d
        WHERE d.adset_id IS NOT NULL AND d.adset_targeting IS NOT NULL AND d.actor_id = ANY (v_pages) AND d.date >= v_today - 120
        ORDER BY d.adset_id, d.date DESC, d._loaded_at DESC) t;
  SELECT d._loaded_at, d._source INTO v_loaded, v_src FROM ads_feed.meta_ads_daily d ORDER BY d._loaded_at DESC LIMIT 1;
  RETURN jsonb_build_object('ok', true, 'from', v_from, 'last_date', v_last, 'loaded_at', v_loaded, 'source', v_src,
                            'rows', v_rows, 'targeting', v_tg);
END $$;
REVOKE ALL ON FUNCTION public.ads_feed_rows(date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.ads_feed_rows(date) TO authenticated;

